/* From Uiverse.io by Sergestra - Tags: button */
.__UIV_SCOPE__ button {
 outline: 0;
 border: 0;
 display: flex;
 flex-direction: column;
 width: 100%;
 max-width: 140px;
 height: 50px;
 border-radius: 0.5em;
 box-shadow: 0 0.625em 1em 0 rgba(30, 143, 255, 0.35);
 overflow: hidden;
}

.__UIV_SCOPE__ button div {
 transform: translateY(0px);
 width: 100%;
}

.__UIV_SCOPE__ button,
.__UIV_SCOPE__ button div {
 transition: 0.6s cubic-bezier(.16,1,.3,1);
}

.__UIV_SCOPE__ button div span {
 display: flex;
 align-items: center;
 justify-content: space-between;
 height: 50px;
 padding: 0.75em 1.125em;
}

.__UIV_SCOPE__ button div:nth-child(1) {
 background-color: #1e90ff;
}

.__UIV_SCOPE__ button div:nth-child(2) {
 background-color: #21dc62;
}

.__UIV_SCOPE__ button:hover {
 box-shadow: 0 0.625em 1em 0 rgba(33, 220, 98, 0.35);
}

.__UIV_SCOPE__ button:hover div {
 transform: translateY(-50px);
}

.__UIV_SCOPE__ button p {
 font-size: 17px;
 font-weight: bold;
 color: #ffffff;
}

.__UIV_SCOPE__ button:active {
 transform: scale(0.95);
}
